import { app } from "@recallfeed/api/app";
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as nextHandler } from "./.open-next/worker.js";
import { dispatch } from "./src/dispatch";
import type { FetchHandler } from "./src/dispatch";
import type { ReflectionFeedEnv } from "./src/env";

/**
 * The production entry point.
 *
 * Every request is checked before anything else runs (see `src/dispatch.ts`): the Access token is
 * verified and must belong to `OWNER_EMAIL`. Then `/api` paths go to the shared Hono app and everything
 * else to the Next.js handler OpenNext generated, both with the verified identity as `ctx.access`.
 *
 * Static asset files (scripts, styles) are served by Cloudflare before this runs. Access still protects
 * them, and they hold no user data.
 */
export default {
  fetch(request: Request, env: ReflectionFeedEnv, ctx: ExecutionContext): Promise<Response> {
    return dispatch(request, env, ctx, { api: app, next: nextHandler as FetchHandler });
  },
} satisfies ExportedHandler<ReflectionFeedEnv>;
